WITH unpacked AS (SELECT id, customer_id, created_at, items, attributes, EXISTS(items, x -> x.price > 100) AS has_premium_item, ARRAY_CONTAINS(coupon_codes, 'VIP') AS used_vip, SIZE(attributes) AS num_attributes, TRY_CAST(attributes['weight_kg'] AS DOUBLE) AS weight_kg, SIZE(items) AS num_items FROM carts) SELECT customer_id, CASE WHEN weight_kg >= 3.9 THEN 'PREMIUM' ELSE 'STANDARD' END AS weight_kg_tier, COUNT(*) AS cnt, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS duration_min FROM unpacked GROUP BY CUBE (customer_id, CASE WHEN weight_kg >= 3.9 THEN 'PREMIUM' ELSE 'STANDARD' END) HAVING duration_min < 1000000;
